/************** Begin file th8_formatting.c **************/
/*
 * th8_formatting.c -- Formatting plugin for TH8.
 *
 * Implements the formatting commands: format and scan.
 *
 * This file is part of the plugin architecture.  The commands
 * are registered via Th8_RegisterPlugin using the static
 * command table returned by th8FormattingGetCommands.
 *
 * Copyright (c) 2026 by Joe Mistachkin.  All rights reserved.
 *
 * See the file "license.terms" for information on usage and redistribution of
 * this file, and for a DISCLAIMER OF ALL WARRANTIES.
 */

#include "th8.h"
/* amalgamation: th8_int.h already included */
/* amalgamation: th8_util.h already included */
/* amalgamation: th8_plugin.h already included */

#if defined(TH8_PLUGIN_FORMATTING)


/*
 *----------------------------------------------------------------------
 *
 * format_command --
 *
 *	Format a string according to %-specifiers.
 *
 *	format FORMATSTRING ?ARG ...?
 *
 *	Supports: %d/%i, %u, %o, %x/%X, %c, %s, %f, %e/%E, %g/%G,
 *	and %%.  Width, precision, and flag characters (-, +, 0,
 *	space, #) are handled.
 *
 * Results:
 *	TH8_OK on success, TH8_ERROR on bad specifier or missing args.
 *
 *----------------------------------------------------------------------
 */

static int
format_command(
    Th8_Interp *interp,
    void *ctx,
    int argc,
    const char **argv,
    size_t *argl)
{
    const char *zFmt;
    size_t nFmt;
    size_t i;
    int iArg = 2;		/* Next argument to consume */
    char *zOut = 0;
    size_t nOut = 0;

    if (argc < 2) {
	return Th8_WrongNumArgs(interp,
		"format formatString ?arg ...?");
    }
    zFmt = argv[1];
    nFmt = TH8_LEN(argl[1]);

    for (i = 0; i < nFmt; i++) {
	if (zFmt[i] != '%') {
	    Th8_StringAppend(interp, &zOut, &nOut,
		    &zFmt[i], 1);
	    continue;
	}
	i++;  /* skip '%' */
	if (i >= nFmt) break;

	/*
	 * Literal %%.
	 */

	if (zFmt[i] == '%') {
	    Th8_StringAppend(interp, &zOut, &nOut, "%", 1);
	    continue;
	}

	/*
	 * Parse flags.
	 */

	{
	    int flagMinus = 0;
	    int flagPlus = 0;
	    int flagZero = 0;
	    int flagSpace = 0;
	    int flagHash = 0;
	    int width = 0;
	    int prec = -1;
	    int havePrec = 0;
	    char spec;
	    char zNum[80];
	    size_t nNum = 0;

	    while (i < nFmt) {
		if (zFmt[i] == '-') flagMinus = 1;
		else if (zFmt[i] == '+') flagPlus = 1;
		else if (zFmt[i] == '0') flagZero = 1;
		else if (zFmt[i] == ' ') flagSpace = 1;
		else if (zFmt[i] == '#') flagHash = 1;
		else break;
		i++;
	    }

	    /*
	     * Width (* = from argument).
	     */

	    if (i < nFmt && zFmt[i] == '*') {
		if (iArg >= argc) {
		    goto not_enough;
		}
		Th8_ToInt(interp, argv[iArg], argl[iArg],
			&width);
		if (width < 0) {
		    flagMinus = 1;
		    width = -width;
		}
		iArg++;
		i++;
	    } else {
		while (i < nFmt && zFmt[i] >= '0'
			&& zFmt[i] <= '9') {
		    width = width * 10 + (zFmt[i] - '0');
		    if (width > 100000) {
			Th8_SetResultStatic(interp,
				"format width too large",
				TH8_NOLEN);
			return TH8_ERROR;
		    }
		    i++;
		}
	    }

	    /*
	     * Precision.
	     */

	    if (i < nFmt && zFmt[i] == '.') {
		i++;
		havePrec = 1;
		prec = 0;
		if (i < nFmt && zFmt[i] == '*') {
		    if (iArg >= argc) {
			goto not_enough;
		    }
		    Th8_ToInt(interp, argv[iArg],
			    argl[iArg], &prec);
		    iArg++;
		    i++;
		} else {
		    while (i < nFmt && zFmt[i] >= '0'
			    && zFmt[i] <= '9') {
			prec = prec * 10 + (zFmt[i] - '0');
			i++;
		    }
		}
	    }

	    if (i >= nFmt) {
		Th8_SetResultStatic(interp,
			"format string ended in middle"
			" of field specifier",
			TH8_NOLEN);
		Th8_Free(interp, zOut);
		return TH8_ERROR;
	    }
	    spec = zFmt[i];

	    switch (spec) {
	    case 'd': case 'i': {
		th8_int64_t val;

		if (iArg >= argc) goto not_enough;
		if (Th8_ToWideInt(interp, argv[iArg],
			argl[iArg], &val) != TH8_OK) {
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}
		iArg++;

		/*
		 * Build the number string with optional
		 * '+' or ' ' prefix.
		 */

		Th8_SetResultWideInt(interp, val);
		{
		    size_t n;
		    const char *z = Th8_GetResult(interp, &n);
		    char *p = zNum;

		    if (z[0] != '-') {
			if (flagPlus) {
			    *p++ = '+';
			} else if (flagSpace) {
			    *p++ = ' ';
			}
		    }
		    while (n > 0 && (size_t)(p - zNum)
			    < sizeof(zNum) - 1) {
			*p++ = *z++;
			n--;
		    }
		    *p = 0;
		    nNum = (size_t)(p - zNum);
		}
		goto fmt_pad_and_emit;
	    }
	    case 'u': {
		th8_int64_t val;

		if (iArg >= argc) goto not_enough;
		if (Th8_ToWideInt(interp, argv[iArg],
			argl[iArg], &val) != TH8_OK) {
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}
		iArg++;
		{
		    th8_uint64_t u = (th8_uint64_t)val;
		    char *p = &zNum[sizeof(zNum) - 1];

		    *p = 0;
		    do {
			*(--p) = (char)('0' + (int)(u % 10));
			u /= 10;
		    } while (u > 0);
		    nNum = (size_t)(&zNum[sizeof(zNum)-1] - p);
		    {
			size_t j;
			for (j = 0; j < nNum; j++) {
			    zNum[j] = p[j];
			}
			zNum[nNum] = 0;
		    }
		}
		goto fmt_pad_and_emit;
	    }
	    case 'o': {
		th8_int64_t val;

		if (iArg >= argc) goto not_enough;
		if (Th8_ToWideInt(interp, argv[iArg],
			argl[iArg], &val) != TH8_OK) {
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}
		iArg++;
		{
		    th8_uint64_t u = (th8_uint64_t)val;
		    char *p = &zNum[sizeof(zNum) - 1];

		    *p = 0;
		    do {
			*(--p) = (char)('0' + (int)(u & 7));
			u >>= 3;
		    } while (u > 0);
		    if (flagHash && *p != '0') {
			*(--p) = '0';
		    }
		    nNum = (size_t)(&zNum[sizeof(zNum)-1] - p);
		    {
			size_t j;
			for (j = 0; j < nNum; j++) {
			    zNum[j] = p[j];
			}
			zNum[nNum] = 0;
		    }
		}
		goto fmt_pad_and_emit;
	    }
	    case 'x': case 'X': {
		th8_int64_t val;
		const char *zHex;

		if (iArg >= argc) goto not_enough;
		zHex = (spec == 'x')
			? "0123456789abcdef"
			: "0123456789ABCDEF";
		if (Th8_ToWideInt(interp, argv[iArg],
			argl[iArg], &val) != TH8_OK) {
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}
		iArg++;
		{
		    th8_uint64_t u = (th8_uint64_t)val;
		    char *p = &zNum[sizeof(zNum) - 1];

		    *p = 0;
		    do {
			*(--p) = zHex[u & 0xF];
			u >>= 4;
		    } while (u > 0);
		    if (flagHash) {
			*(--p) = (spec == 'x') ? 'x' : 'X';
			*(--p) = '0';
		    }
		    nNum = (size_t)(&zNum[sizeof(zNum)-1] - p);
		    {
			size_t j;
			for (j = 0; j < nNum; j++) {
			    zNum[j] = p[j];
			}
			zNum[nNum] = 0;
		    }
		}
		goto fmt_pad_and_emit;
	    }
	    case 'c': {
		th8_int64_t val;
		int nBytes;

		if (iArg >= argc) goto not_enough;
		if (Th8_ToWideInt(interp, argv[iArg],
			argl[iArg], &val) != TH8_OK) {
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}
		iArg++;
		nBytes = Th8_Utf8Encode((int)val, zNum);
		zNum[nBytes] = 0;
		nNum = (size_t)nBytes;
		goto fmt_pad_and_emit;
	    }
	    case 's': {
		size_t nVal;
		const char *zVal;

		if (iArg >= argc) goto not_enough;
		zVal = argv[iArg];
		nVal = TH8_LEN(argl[iArg]);
		if (havePrec && prec >= 0
			&& (size_t)prec < nVal) {
		    nVal = (size_t)prec;
		}
		iArg++;

		/*
		 * Copy to zNum for width/padding.
		 */

		if (nVal >= sizeof(zNum)) {
		    nVal = sizeof(zNum) - 1;
		}
		{
		    size_t j;
		    for (j = 0; j < nVal; j++) {
			zNum[j] = zVal[j];
		    }
		    zNum[nVal] = 0;
		    nNum = nVal;
		}
		goto fmt_pad_and_emit;
	    }
	    case 'f': case 'e': case 'E': case 'g': case 'G': {
		double rVal;
		char zFBuf[80];
		char *fp = zFBuf;
		int nPrec;
		int neg;
		double abs_v;
		th8_int64_t iPart;
		double fPart;
		int k;
		int expn_e = 0;
		double mant_e = 0.0;
		int stripGZeros = 0;

		if (iArg >= argc) goto not_enough;
		if (Th8_ToDouble(interp, argv[iArg],
			argl[iArg], &rVal) != TH8_OK) {
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}
		iArg++;
		nPrec = havePrec ? prec : 6;
		if (nPrec < 0) nPrec = 0;
		if (nPrec > 40) nPrec = 40;

		neg = (rVal < 0.0);
		abs_v = neg ? -rVal : rVal;

		if (spec == 'e' || spec == 'E') {
		fmt_scientific:
		    /*
		     * Scientific notation: M.DDDe+EE
		     */

		    expn_e = 0;
		    mant_e = abs_v;

		    if (abs_v != 0.0) {
			double lg;

			if (th8MathOp(interp, TH8_MATH_LOG10,
				&lg, abs_v, 0.0) == TH8_OK) {
			    if (lg < 0.0) {
				lg -= 1.0;
			    }
			    expn_e = (int)lg;
			    if (expn_e < -307) expn_e = -307;
			    if (expn_e > 307) expn_e = 307;
			    {
				double pwr;

				th8MathOp(interp, TH8_MATH_POW,
					&pwr, 10.0, (double)expn_e);
				if (pwr != 0.0) mant_e = abs_v / pwr;
			    }
			    while (mant_e >= 10.0) {
				mant_e /= 10.0;
				expn_e++;
			    }
			    while (mant_e < 1.0 && mant_e > 0.0) {
				mant_e *= 10.0;
				expn_e--;
			    }
			} else {
			    goto fmt_fixed;
			}
		    }

		    if (neg) *fp++ = '-';
		    iPart = (th8_int64_t)mant_e;
		    fPart = mant_e - (double)iPart;
		    *fp++ = (char)('0' + (int)(iPart % 10));
		    if (nPrec > 0) {
			*fp++ = '.';
			for (k = 0; k < nPrec; k++) {
			    fPart *= 10.0;
			    *fp++ = (char)('0' + (int)fPart);
			    fPart -= (int)fPart;
			}
			if (fPart >= 0.5 && fp > zFBuf) {
			    char *rp = fp - 1;

			    while (rp >= zFBuf) {
				if (*rp == '.') { rp--; continue; }
				if (*rp < '9') { (*rp)++; break; }
				*rp = '0';
				rp--;
			    }
			}
		    }
		    *fp++ = (spec == 'E') ? 'E' : 'e';
		    if (expn_e >= 0) {
			*fp++ = '+';
		    } else {
			*fp++ = '-';
			expn_e = -expn_e;
		    }
		    if (expn_e >= 100) {
			*fp++ = (char)('0' + expn_e / 100);
			*fp++ = (char)('0' + (expn_e / 10) % 10);
			*fp++ = (char)('0' + expn_e % 10);
		    } else {
			*fp++ = (char)('0' + expn_e / 10);
			*fp++ = (char)('0' + expn_e % 10);
		    }
		} else if (spec == 'g' || spec == 'G') {
		    /*
		     * General: use %e if exponent < -4 or >= prec,
		     * otherwise %f.  Strip trailing zeros.
		     */

		    int expn = 0;
		    int gPrec = (nPrec == 0) ? 1 : nPrec;

		    if (abs_v != 0.0) {
			double lg;

			if (th8MathOp(interp, TH8_MATH_LOG10,
				&lg, abs_v, 0.0) == TH8_OK) {
			    if (lg >= 0.0) {
				expn = (int)lg;
			    } else {
				expn = (int)lg - 1;
			    }
			}
		    }
		    if (expn < -4 || expn >= gPrec) {
			/* Use scientific notation with gPrec-1 digits */
			prec = gPrec - 1;
			havePrec = 1;
			nPrec = prec;
			spec = (spec == 'G') ? 'E' : 'e';
			stripGZeros = 1;
			goto fmt_scientific;
		    } else {
			/* Use fixed notation with gPrec - 1 - expn digits */
			int fPrec = gPrec - 1 - expn;

			if (fPrec < 0) fPrec = 0;
			if (neg) *fp++ = '-';
			iPart = (th8_int64_t)abs_v;
			fPart = abs_v - (double)iPart;
			/* Integer part */
			{
			    char zInt[30];
			    char *p = &zInt[sizeof(zInt) - 1];
			    th8_int64_t v = iPart;

			    *p = 0;
			    do {
				*(--p) = (char)('0' + (int)(v % 10));
				v /= 10;
			    } while (v > 0);
			    while (*p) *fp++ = *p++;
			}
			if (fPrec > 0) {
			    *fp++ = '.';
			    for (k = 0; k < fPrec; k++) {
				fPart *= 10.0;
				*fp++ = (char)('0' + (int)fPart);
				fPart -= (int)fPart;
			    }
			    /* Strip trailing zeros */
			    while (fp > zFBuf && *(fp - 1) == '0') fp--;
			    if (fp > zFBuf && *(fp - 1) == '.') fp--;
			}
		    }
		} else {
		    /*
		     * Fixed-point: DDDD.DDD with nPrec digits
		     * after the decimal point.
		     */

		fmt_fixed:
		    if (neg) *fp++ = '-';
		    iPart = (th8_int64_t)abs_v;
		    fPart = abs_v - (double)iPart;
		    /* Round integer part when precision is 0. */
		    if (nPrec == 0 && fPart >= 0.5) {
			iPart++;
			fPart = 0.0;
		    }
		    /* Integer part */
		    {
			char zInt[30];
			char *p = &zInt[sizeof(zInt) - 1];
			th8_int64_t v = iPart;

			*p = 0;
			do {
			    *(--p) = (char)('0' + (int)(v % 10));
			    v /= 10;
			} while (v > 0);
			while (*p) *fp++ = *p++;
		    }
		    if (nPrec > 0) {
			*fp++ = '.';
			for (k = 0; k < nPrec; k++) {
			    fPart *= 10.0;
			    *fp++ = (char)('0' + (int)fPart);
			    fPart -= (int)fPart;
			}
			/* Round last digit */
			if (fPart >= 0.5 && fp > zFBuf) {
			    char *rp = fp - 1;

			    while (rp >= zFBuf) {
				if (*rp == '.') { rp--; continue; }
				if (*rp < '9') { (*rp)++; break; }
				*rp = '0';
				rp--;
			    }
			}
		    }
		}
		/*
		 * For %g: strip trailing zeros from the
		 * mantissa before the exponent.
		 */

		if (stripGZeros) {
		    char *ep = zFBuf;
		    char *dp = 0;

		    /* Find the 'e' or 'E'. */
		    while (ep < fp && *ep != 'e' && *ep != 'E') {
			if (*ep == '.') dp = ep;
			ep++;
		    }
		    if (dp && ep < fp) {
			char *zp = ep - 1;

			while (zp > dp && *zp == '0') zp--;
			if (zp == dp) zp--;  /* remove '.' too */
			zp++;
			/* Shift exponent part down. */
			while (ep < fp) {
			    *zp++ = *ep++;
			}
			fp = zp;
		    }
		}
		nNum = (size_t)(fp - zFBuf);
		if (nNum >= sizeof(zNum)) {
		    nNum = sizeof(zNum) - 1;
		}
		{
		    size_t j;
		    for (j = 0; j < nNum; j++) {
			zNum[j] = zFBuf[j];
		    }
		    zNum[nNum] = 0;
		}
		goto fmt_pad_and_emit;
	    }
	    default:
		{
		    char zBad[2];

		    zBad[0] = spec;
		    zBad[1] = 0;
		    Th8_ErrorMessage(interp,
			    "bad field specifier \"",
			    zBad, 1);
		    Th8_Free(interp, zOut);
		    return TH8_ERROR;
		}

	    /*
	     * Common pad-and-emit path.  Specifiers that build
	     * their output in zNum/nNum jump here for width and
	     * alignment handling.
	     */

	    fmt_pad_and_emit:
		if (width > 0
			&& nNum < (size_t)width) {
		    size_t pad = (size_t)width - nNum;
		    size_t k;
		    char cPad = flagZero ? '0' : ' ';

		    if (flagMinus) {
			/*
			 * Left-justify: content then spaces.
			 */

			Th8_StringAppend(interp,
				&zOut, &nOut, zNum, nNum);
			for (k = 0; k < pad; k++) {
			    Th8_StringAppend(interp,
				    &zOut, &nOut, " ", 1);
			}
		    } else if (flagZero && nNum > 0
			    && (zNum[0] == '-' || zNum[0] == '+')) {
			/*
			 * Zero-pad with sign: sign first, then
			 * zeros, then digits.
			 */

			Th8_StringAppend(interp,
				&zOut, &nOut, zNum, 1);
			for (k = 0; k < pad; k++) {
			    Th8_StringAppend(interp,
				    &zOut, &nOut, "0", 1);
			}
			Th8_StringAppend(interp,
				&zOut, &nOut,
				&zNum[1], nNum - 1);
		    } else {
			/*
			 * Right-justify with padding char.
			 */

			for (k = 0; k < pad; k++) {
			    Th8_StringAppend(interp,
				    &zOut, &nOut,
				    &cPad, 1);
			}
			Th8_StringAppend(interp,
				&zOut, &nOut, zNum, nNum);
		    }
		} else {
		    Th8_StringAppend(interp,
			    &zOut, &nOut, zNum, nNum);
		}
		break;
	    }
	}
    }

    Th8_SetResult(interp, zOut, nOut);
    Th8_Free(interp, zOut);
    return TH8_OK;

not_enough:
    Th8_Free(interp, zOut);
    Th8_SetResultStatic(interp,
	    "not enough arguments for all format specifiers",
	    TH8_NOLEN);
    return TH8_ERROR;
}


/*
 *----------------------------------------------------------------------
 *
 * scan_command --
 *
 *	Parse a string according to a format (inverse of format).
 *
 *	scan STRING FORMAT ?VARNAME ...?
 *
 *	Simplified implementation supporting %d/%i, %o, %x, %s, %c,
 *	%f, and %n.  Width specifiers are parsed but not enforced.
 *
 *	Two modes of operation:
 *	  - Variable mode (argc > 3): each converted value is stored
 *	    in the corresponding VARNAME; the result is the count
 *	    of successful conversions.
 *	  - List mode (argc == 3): converted values are collected
 *	    into a list which becomes the result.
 *
 *	The parsing loop walks the format string (iFmt) and input
 *	string (iStr) in lockstep:
 *	  - Non-'%' format characters must match literally.
 *	  - %% matches a literal '%'.
 *	  - Each specifier consumes characters from the input,
 *	    converts them, and stores/collects the result.
 *	  - Parsing stops on the first mismatch or conversion failure.
 *
 *	NOTE: This is a simplified implementation.  Width limits on
 *	specifiers, character classes ([...]), and the * suppression
 *	flag are not yet supported.
 *
 *----------------------------------------------------------------------
 */

static int
scan_command(
    Th8_Interp *interp,
    void *ctx,
    int argc,
    const char **argv,
    size_t *argl)
{
    const char *zStr;
    size_t nStr;
    const char *zFmt;
    size_t nFmt;
    size_t iStr = 0;
    size_t iFmt = 0;
#if defined(TH8_ENABLE_VARIABLES)
    int iVar = 3;		/* Next variable argument */
#endif
    int nConv = 0;		/* Conversions performed */
    char *zList = 0;		/* For no-variable mode */
    size_t nList = 0;
    int bVarMode;

    if (argc < 3) {
	return Th8_WrongNumArgs(interp,
		"scan string format ?varname ...?");
    }
    zStr = argv[1];
    nStr = TH8_LEN(argl[1]);
    zFmt = argv[2];
    nFmt = TH8_LEN(argl[2]);
    bVarMode = (argc > 3);

#if !defined(TH8_ENABLE_VARIABLES)
    if (bVarMode) {
	Th8_SetResultStatic(interp, "variable resolution not available", TH8_NOLEN);
	return TH8_ERROR;
    }
#endif

    while (iFmt < nFmt && iStr <= nStr) {
	if (zFmt[iFmt] != '%') {
	    /*
	     * Literal character must match.
	     */

	    if (iStr >= nStr || zStr[iStr] != zFmt[iFmt]) {
		break;
	    }
	    iStr++;
	    iFmt++;
	    continue;
	}
	iFmt++;  /* skip '%' */
	if (iFmt >= nFmt) break;
	if (zFmt[iFmt] == '%') {
	    /* Literal %% */
	    if (iStr >= nStr || zStr[iStr] != '%') break;
	    iStr++;
	    iFmt++;
	    continue;
	}

	/*
	 * Skip optional width (not used in simplified impl).
	 */

	while (iFmt < nFmt && zFmt[iFmt] >= '0'
		&& zFmt[iFmt] <= '9') {
	    iFmt++;
	}
	if (iFmt >= nFmt) break;

	switch (zFmt[iFmt]) {
	case 'd': case 'i': {
	    /*
	     * Decimal integer.
	     */

	    size_t start = iStr;
	    th8_int64_t val;

	    if (iStr < nStr && (zStr[iStr] == '-'
		    || zStr[iStr] == '+')) {
		iStr++;
	    }
	    while (iStr < nStr && zStr[iStr] >= '0'
		    && zStr[iStr] <= '9') {
		iStr++;
	    }
	    if (iStr == start) goto scan_done;
	    if (Th8_ToWideInt(0, &zStr[start],
		    iStr - start, &val) != TH8_OK) {
		goto scan_done;
	    }
	    Th8_SetResultWideInt(interp, val);
	    break;
	}
	case 'o': {
	    size_t start = iStr;
	    th8_int64_t val = 0;

	    while (iStr < nStr && zStr[iStr] >= '0'
		    && zStr[iStr] <= '7') {
		if (val > (TH8_INT64_MAX >> 3)) {
		    Th8_SetResultStatic(interp,
			    "integer value too large",
			    TH8_NOLEN);
		    return TH8_ERROR;
		}
		val = (val << 3) | (zStr[iStr] - '0');
		iStr++;
	    }
	    if (iStr == start) goto scan_done;
	    Th8_SetResultWideInt(interp, val);
	    break;
	}
	case 'x': {
	    size_t start;
	    th8_int64_t val = 0;

	    /*
	     * Skip optional 0x or 0X prefix.
	     */

	    if (iStr + 1 < nStr && zStr[iStr] == '0'
		    && (zStr[iStr + 1] == 'x'
			|| zStr[iStr + 1] == 'X')) {
		iStr += 2;
	    }
	    start = iStr;
	    while (iStr < nStr && th8IsHexDig(zStr[iStr])) {
		int d;

		if (zStr[iStr] >= '0' && zStr[iStr] <= '9') {
		    d = zStr[iStr] - '0';
		} else if (zStr[iStr] >= 'a') {
		    d = zStr[iStr] - 'a' + 10;
		} else {
		    d = zStr[iStr] - 'A' + 10;
		}
		if (val > (TH8_INT64_MAX >> 4)) {
		    Th8_SetResultStatic(interp,
			    "integer value too large",
			    TH8_NOLEN);
		    return TH8_ERROR;
		}
		val = (val << 4) | d;
		iStr++;
	    }
	    if (iStr == start) goto scan_done;
	    Th8_SetResultWideInt(interp, val);
	    break;
	}
	case 'c': {
	    /*
	     * Single character -> code point value.
	     */

	    int nByte;
	    int cp;

	    if (iStr >= nStr) goto scan_done;
	    cp = Th8_Utf8Decode(&zStr[iStr], nStr - iStr,
		    &nByte);
	    iStr += (size_t)nByte;
	    Th8_SetResultInt(interp, cp);
	    break;
	}
	case 's': {
	    /*
	     * Non-whitespace string.
	     */

	    size_t start = iStr;

	    while (iStr < nStr && !th8IsSpace(zStr[iStr])) {
		iStr++;
	    }
	    Th8_SetResult(interp, &zStr[start],
		    iStr - start);
	    break;
	}
	case 'f': {
	    /*
	     * Floating-point number.
	     */

	    size_t start = iStr;
	    double rVal;

	    if (iStr < nStr && (zStr[iStr] == '-'
		    || zStr[iStr] == '+')) {
		iStr++;
	    }
	    while (iStr < nStr && ((zStr[iStr] >= '0'
		    && zStr[iStr] <= '9')
		    || zStr[iStr] == '.'
		    || zStr[iStr] == 'e'
		    || zStr[iStr] == 'E')) {
		iStr++;
	    }
	    if (iStr == start) goto scan_done;
	    if (Th8_ToDouble(0, &zStr[start],
		    iStr - start, &rVal) != TH8_OK) {
		goto scan_done;
	    }
	    Th8_SetResultDouble(interp, rVal);
	    break;
	}
	case 'n': {
	    /*
	     * Number of characters consumed so far.
	     */

	    Th8_SetResultInt(interp,
		    Th8_Utf8Len(zStr, iStr));
	    break;
	}
	default:
	    goto scan_done;
	}
	iFmt++;

	/*
	 * Store or collect the converted value.
	 */

	{
	    size_t nRes;
	    const char *zRes = Th8_GetResult(interp, &nRes);

	    if (bVarMode) {
#if defined(TH8_ENABLE_VARIABLES)
		if (iVar < argc) {
		    Th8_SetVar(interp, argv[iVar],
			    TH8_LEN(argl[iVar]),
			    zRes, nRes);
		    iVar++;
		}
#endif
	    } else {
		Th8_ListAppend(interp, &zList, &nList,
			zRes, nRes);
	    }
	}
	nConv++;
    }

scan_done:
    if (bVarMode) {
	Th8_SetResultInt(interp, nConv);
    } else {
	Th8_SetResult(interp, zList, nList);
	Th8_Free(interp, zList);
    }
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * Command table and plugin registration.
 *
 *----------------------------------------------------------------------
 */

static Th8_CommandEntry th8FormattingCommands[] = {
    { 1, 0, "format",	format_command },
    { 1, 0, "scan",	scan_command },
};

int
th8FormattingGetCommands(
    Th8_CommandEntry *pCommand,
    int *pnCommand)
{
    int n = (int)(sizeof(th8FormattingCommands)
	    / sizeof(th8FormattingCommands[0]));

    if (!pnCommand) return TH8_ERROR;
    if (!pCommand) {
	*pnCommand = n;
	return TH8_OK;
    }
    if (*pnCommand < n) return TH8_ERROR;
    *pnCommand = n;
    {
	int i;

	for (i = 0; i < n; i++) {
	    pCommand[i] = th8FormattingCommands[i];
	}
    }
    return TH8_OK;
}
#endif /* TH8_PLUGIN_FORMATTING */

