    Th8_Eval(interp, 0,
	    "catch {namespace eval ::th8testlib {}}", TH8_NOLEN,
	    NULL, 0);
    Th8_CreateCommand(interp,
	    "::th8testlib::nop",
	    th8test_nop_cmd, 0, 0, 0);
