/* d = a + b (mod c) */
mp_err mp_addmod(const mp_int *a, const mp_int *b, const mp_int *c, mp_int *d)
{
   mp_err err;
   if ((err = mp_add(a, b, d)) != MP_OKAY) {
      return err;
   }
   return mp_mod(d, c, d);
}
#endif

