#define MP_DEFAULT_MUL_TOOM_CUTOFF      350
#define MP_DEFAULT_SQR_TOOM_CUTOFF      400

/*** End: tommath_cutoffs.h ***/
#  define MP_MUL_KARATSUBA_CUTOFF MP_DEFAULT_MUL_KARATSUBA_CUTOFF
