/*
 * th8_attrflags.c -- Attribute flags subsystem for TH8.
 *
 * Implements an Eagle compatible attribute flags string format:
 *
 *   Simple:  "abc"          -- flag characters for the default key
 *   Complex: "{HEXKEY:abc}" -- per-key flag characters in braces
 *   Mixed:   "abc{HEXKEY:xy}" -- default flags + keyed flags
 *
 * Change specifications use prefixes: +add, -remove, =set
 *
 * This is a port of Eagle's AttributeFlags.cs to plain C.
 *
 * Copyright (c) 2026 by Joe Mistachkin.  All rights reserved.
 *
 * See the file "license.terms" for information on usage and redistribution of
 * this file, and for a DISCLAIMER OF ALL WARRANTIES.
 */

#include "th8.h"


/*
 *----------------------------------------------------------------------
 *
 * Constants and helpers.
 *
 *----------------------------------------------------------------------
 */

#define AF_NAME_SEP       ':'
#define AF_MAX_NAME_LEN   16	/* hex digits in a 64-bit key */

/*
 * th8AfFormatHex -- format a 64-bit unsigned value as uppercase hex.
 *
 *	Writes into zBuf (must have room for at least 17 bytes).
 *	If bPad is true, zero-pads to exactly 16 digits.
 *	Returns the number of characters written (not counting NUL).
 *	No CRT dependency.
 */

static int
th8AfFormatHex(char *zBuf, th8_uint64_t u, int bPad)
{
    static const char zHex[] = "0123456789ABCDEF";
    char tmp[16];
    int tn = 0;
    int n = 0;

    do {
	tmp[tn++] = zHex[u & 0xF];
	u >>= 4;
    } while (u > 0);
    if (bPad) {
	while (tn < 16) tmp[tn++] = '0';
    }
    while (tn > 0) {
	zBuf[n++] = tmp[--tn];
    }
    zBuf[n] = 0;
    return n;
}
#define AF_ADD_CHAR       '+'
#define AF_REMOVE_CHAR    '-'
#define AF_SET_CHAR       '='

static int
th8AfIsHexDigit(char c)
{
    return (c >= '0' && c <= '9')
	|| (c >= 'a' && c <= 'f')
	|| (c >= 'A' && c <= 'F');
}

static int
th8AfIsIdentChar(char c)
{
    return (c >= '0' && c <= '9')
	|| (c >= 'a' && c <= 'z')
	|| (c >= 'A' && c <= 'Z')
	|| c == '_';
}

static int
th8AfIsSpace(char c)
{
    return c == ' ' || c == '\t' || c == '\r' || c == '\n';
}


/*
 *----------------------------------------------------------------------
 *
 * Per-key flag set helpers.
 *
 *----------------------------------------------------------------------
 */

static void
th8AfFlagSetInit(Th8_Interp *interp, Th8_FlagSet *p)
{
    Th8_Memset(interp, p, 0, sizeof(Th8_FlagSet));
}

static void
th8AfFlagSetAdd(Th8_FlagSet *p, char c)
{
    if ((unsigned char)c < 128 && !p->present[(unsigned char)c]) {
	p->present[(unsigned char)c] = 1;
	if (p->nOrder < 128) {
	    p->order[p->nOrder++] = c;
	}
    }
}

static void
th8AfFlagSetRemove(Th8_FlagSet *p, char c)
{
    if ((unsigned char)c < 128 && p->present[(unsigned char)c]) {
	int i, j;

	p->present[(unsigned char)c] = 0;
	for (i = 0, j = 0; i < p->nOrder; i++) {
	    if (p->order[i] != c) {
		p->order[j++] = p->order[i];
	    }
	}
	p->nOrder = j;
    }
}

static int
th8AfFlagSetHas(const Th8_FlagSet *p, char c)
{
    return ((unsigned char)c < 128) ? p->present[(unsigned char)c] : 0;
}

/* th8AfFlagSetAddString removed -- unused; add back if needed. */


/*
 *----------------------------------------------------------------------
 *
 * Key-to-flagset map -- array of (key, FlagSet) pairs.
 * Key 0 is the "default" (non-keyed) flags.
 *
 *----------------------------------------------------------------------
 */

/* Types defined in th8.h: Th8_FlagSet, Th8_AfKeyEntry, Th8_AfMap */

#define AF_MAX_KEYS TH8_AF_MAX_KEYS

static void
th8AfMapInit(Th8_AfMap *p)
{
    p->n = 0;
}

static Th8_FlagSet *
th8AfMapGet(Th8_Interp *interp, Th8_AfMap *p, th8_int64_t key,
    int bCreate)
{
    int i;

    for (i = 0; i < p->n; i++) {
	if (p->a[i].key == key) return &p->a[i].flags;
    }
    if (bCreate && p->n < AF_MAX_KEYS) {
	i = p->n++;
	p->a[i].key = key;
	th8AfFlagSetInit(interp, &p->a[i].flags);
	return &p->a[i].flags;
    }
    return NULL;
}


/*
 *----------------------------------------------------------------------
 *
 * th8AfParseHexKey --
 *
 *	Parse a hex string into a 64-bit key value.
 *
 *----------------------------------------------------------------------
 */

static int
th8AfParseHexKey(const char *z, size_t n, th8_int64_t *pKey)
{
    th8_int64_t val = 0;
    size_t i;

    for (i = 0; i < n; i++) {
	char c = z[i];
	int d;

	if (c >= '0' && c <= '9') d = c - '0';
	else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
	else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
	else return TH8_ERROR;
	val = (val << 4) | d;
    }
    *pKey = val;
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_AttrFlagsParse --
 *
 *	Parse an attribute flags string into a key-to-flagset map.
 *
 *----------------------------------------------------------------------
 */

int
Th8_AttrFlagsParse(
    Th8_Interp *interp,
    const char *zText,
    size_t nText,
    int bComplex,
    int bSpace,
    Th8_AfMap *pMap)
{
    size_t i = 0;
    char zName[AF_MAX_NAME_LEN + 1];
    int nName = 0;
    int bOpen = 0;
    int bHaveName = 0;
    int bNameSepOk = 1;
    th8_int64_t key = 0;

    th8AfMapInit(pMap);
    if (!zText) return TH8_OK;
    if (nText == TH8_NOLEN) nText = Th8_Strlen(interp, zText);

    for (i = 0; i < nText; i++) {
	char c = zText[i];

	if (c == '{') {
	    if (!bComplex) {
		Th8_SetResultStatic(interp,
			"flags: unexpected '{' in simple mode",
			TH8_NOLEN);
		return TH8_ERROR;
	    }
	    if (bOpen) {
		Th8_SetResultStatic(interp,
			"flags: nested '{'", TH8_NOLEN);
		return TH8_ERROR;
	    }
	    bOpen = 1;
	    nName = 0;
	    bHaveName = 0;
	    bNameSepOk = 1;
	    continue;
	}

	if (c == '}') {
	    if (!bComplex || !bOpen) {
		Th8_SetResultStatic(interp,
			"flags: unexpected '}'", TH8_NOLEN);
		return TH8_ERROR;
	    }
	    if (!bHaveName || nName == 0) {
		Th8_SetResultStatic(interp,
			"flags: '}' without complete key",
			TH8_NOLEN);
		return TH8_ERROR;
	    }
	    /* Key was already parsed when bHaveName was set. */
	    bOpen = 0;
	    bHaveName = 0;
	    bNameSepOk = 1;
	    continue;
	}

	if (bOpen && !bHaveName) {
	    /* Inside braces, collecting hex key name. */
	    if (bSpace && th8AfIsSpace(c)) continue;

	    if (c == AF_NAME_SEP) {
		if (nName == 0) {
		    Th8_SetResultStatic(interp,
			    "flags: ':' without key name",
			    TH8_NOLEN);
		    return TH8_ERROR;
		}
		zName[nName] = 0;
		if (th8AfParseHexKey(zName, (size_t)nName,
			&key) != TH8_OK) {
		    Th8_SetResultStatic(interp,
			    "flags: invalid hex key",
			    TH8_NOLEN);
		    return TH8_ERROR;
		}
		bHaveName = 1;
		bNameSepOk = 0;
		continue;
	    }

	    if (!th8AfIsHexDigit(c)) {
		Th8_SetResultStatic(interp,
			"flags: invalid key character",
			TH8_NOLEN);
		return TH8_ERROR;
	    }

	    if (nName >= AF_MAX_NAME_LEN) {
		Th8_SetResultStatic(interp,
			"flags: key too long", TH8_NOLEN);
		return TH8_ERROR;
	    }
	    zName[nName++] = c;

	    /* Legacy format: 16 hex digits with no colon. */
	    if (nName == AF_MAX_NAME_LEN && bNameSepOk) {
		zName[nName] = 0;
		if (th8AfParseHexKey(zName, (size_t)nName,
			&key) != TH8_OK) {
		    Th8_SetResultStatic(interp,
			    "flags: invalid hex key",
			    TH8_NOLEN);
		    return TH8_ERROR;
		}
		bHaveName = 1;
	    }
	    continue;
	}

	/* Value character (flag). */
	if (bSpace && th8AfIsSpace(c)) continue;

	if (c == AF_NAME_SEP && bComplex) {
	    /* Colon outside braces in complex mode. */
	    if (!bNameSepOk) {
		Th8_SetResultStatic(interp,
			"flags: unexpected ':'", TH8_NOLEN);
		return TH8_ERROR;
	    }
	    bNameSepOk = 0;
	    continue;
	}

	if (!th8AfIsIdentChar(c)) {
	    Th8_SetResultStatic(interp,
		    "flags: invalid flag character",
		    TH8_NOLEN);
	    return TH8_ERROR;
	}

	{
	    th8_int64_t useKey = bOpen ? key : 0;
	    Th8_FlagSet *pFs = th8AfMapGet(interp, pMap, useKey, 1);

	    if (!pFs) {
		Th8_SetResultStatic(interp,
			"flags: too many keys", TH8_NOLEN);
		return TH8_ERROR;
	    }
	    th8AfFlagSetAdd(pFs, c);
	}
    }

    if (bOpen) {
	Th8_SetResultStatic(interp,
		"flags: missing '}'", TH8_NOLEN);
	return TH8_ERROR;
    }

    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_AttrFlagsFormat --
 *
 *	Format a flag map back to a string.
 *
 *----------------------------------------------------------------------
 */

int
Th8_AttrFlagsFormat(
    Th8_Interp *interp,
    const Th8_AfMap *pMap,
    int bLegacy,
    int bCompact,
    int bSpace,
    int bSort,
    char **pzOut,
    size_t *pnOut)
{
    char *zOut = NULL;
    size_t nOut = 0;
    int i, c;

    (void)bCompact; /* reserved */

    for (i = 0; i < pMap->n; i++) {
	th8_int64_t key = pMap->a[i].key;
	const Th8_FlagSet *pFs = &pMap->a[i].flags;

	if (bSpace && nOut > 0) {
	    Th8_StringAppend(interp, &zOut, &nOut, " ", 1);
	}

	if (key != 0) {
	    char zBuf[18];  /* 16 hex + ':' + NUL */
	    int n;

	    Th8_StringAppend(interp, &zOut, &nOut, "{", 1);
	    n = th8AfFormatHex(zBuf, (th8_uint64_t)key, bLegacy);
	    if (!bLegacy) {
		zBuf[n++] = ':';
		zBuf[n] = 0;
	    }
	    Th8_StringAppend(interp, &zOut, &nOut,
		    zBuf, (size_t)n);

	    if (bSort) {
		for (c = 0; c < 128; c++) {
		    if (pFs->present[c]) {
			char ch = (char)c;

			Th8_StringAppend(interp, &zOut, &nOut,
				&ch, 1);
		    }
		}
	    } else {
		/* Insertion order. */
		for (c = 0; c < pFs->nOrder; c++) {
		    Th8_StringAppend(interp, &zOut, &nOut,
			    &pFs->order[c], 1);
		}
	    }
	    Th8_StringAppend(interp, &zOut, &nOut, "}", 1);
	} else {
	    /* Default key: emit flags. */
	    if (bSort) {
		for (c = 0; c < 128; c++) {
		    if (pFs->present[c]) {
			char ch = (char)c;

			Th8_StringAppend(interp, &zOut, &nOut,
				&ch, 1);
		    }
		}
	    } else {
		for (c = 0; c < pFs->nOrder; c++) {
		    Th8_StringAppend(interp, &zOut, &nOut,
			    &pFs->order[c], 1);
		}
	    }
	}
    }

    *pzOut = zOut;
    *pnOut = nOut;
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * Wildcard expansion.
 *
 *	*  = all alphanumeric (0-9, A-Z, a-z)
 *	#  = all digits (0-9)
 *	!  = all letters (A-Z, a-z)
 *	$  = uppercase letters (A-Z)
 *	@  = lowercase letters (a-z)
 *
 *----------------------------------------------------------------------
 */

static int
th8AfIsWildcard(char c)
{
    return c == '*' || c == '#' || c == '!'
	|| c == '$' || c == '@';
}

static void
th8AfExpandWildcard(char wc, Th8_FlagSet *pFs,
    void (*xOp)(Th8_FlagSet *, char))
{
    int c;

    switch (wc) {
    case '*':
	for (c = '0'; c <= '9'; c++) xOp(pFs, (char)c);
	for (c = 'A'; c <= 'Z'; c++) xOp(pFs, (char)c);
	for (c = 'a'; c <= 'z'; c++) xOp(pFs, (char)c);
	break;
    case '#':
	for (c = '0'; c <= '9'; c++) xOp(pFs, (char)c);
	break;
    case '!':
	for (c = 'A'; c <= 'Z'; c++) xOp(pFs, (char)c);
	for (c = 'a'; c <= 'z'; c++) xOp(pFs, (char)c);
	break;
    case '$':
	for (c = 'A'; c <= 'Z'; c++) xOp(pFs, (char)c);
	break;
    case '@':
	for (c = 'a'; c <= 'z'; c++) xOp(pFs, (char)c);
	break;
    }
}

/*
 * Check if a flag set contains ALL characters in a wildcard
 * expansion.  Returns 1 if all present, 0 otherwise.
 */

static int
th8AfWildcardHaveAll(const Th8_FlagSet *pFs, char wc)
{
    int c;

    switch (wc) {
    case '*':
	for (c = '0'; c <= '9'; c++)
	    if (!pFs->present[c]) return 0;
	for (c = 'A'; c <= 'Z'; c++)
	    if (!pFs->present[c]) return 0;
	for (c = 'a'; c <= 'z'; c++)
	    if (!pFs->present[c]) return 0;
	return 1;
    case '#':
	for (c = '0'; c <= '9'; c++)
	    if (!pFs->present[c]) return 0;
	return 1;
    case '!':
	for (c = 'A'; c <= 'Z'; c++)
	    if (!pFs->present[c]) return 0;
	for (c = 'a'; c <= 'z'; c++)
	    if (!pFs->present[c]) return 0;
	return 1;
    case '$':
	for (c = 'A'; c <= 'Z'; c++)
	    if (!pFs->present[c]) return 0;
	return 1;
    case '@':
	for (c = 'a'; c <= 'z'; c++)
	    if (!pFs->present[c]) return 0;
	return 1;
    }
    return 0;
}

static int
th8AfWildcardHaveAny(const Th8_FlagSet *pFs, char wc)
{
    int c;

    switch (wc) {
    case '*':
	for (c = '0'; c <= '9'; c++)
	    if (pFs->present[c]) return 1;
	for (c = 'A'; c <= 'Z'; c++)
	    if (pFs->present[c]) return 1;
	for (c = 'a'; c <= 'z'; c++)
	    if (pFs->present[c]) return 1;
	return 0;
    case '#':
	for (c = '0'; c <= '9'; c++)
	    if (pFs->present[c]) return 1;
	return 0;
    case '!':
	for (c = 'A'; c <= 'Z'; c++)
	    if (pFs->present[c]) return 1;
	for (c = 'a'; c <= 'z'; c++)
	    if (pFs->present[c]) return 1;
	return 0;
    case '$':
	for (c = 'A'; c <= 'Z'; c++)
	    if (pFs->present[c]) return 1;
	return 0;
    case '@':
	for (c = 'a'; c <= 'z'; c++)
	    if (pFs->present[c]) return 1;
	return 0;
    }
    return 0;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_AttrFlagsHave --
 *
 *	Check if a flag set contains the requested flags.
 *
 *----------------------------------------------------------------------
 */

int
Th8_AttrFlagsHave(
    const Th8_AfMap *pMap,
    th8_int64_t key,
    const char *zHave,
    size_t nHave,
    int bAll,
    int bStrict)
{
    const Th8_FlagSet *pFs;
    size_t i;

    pFs = NULL;
    {
	int j;

	for (j = 0; j < pMap->n; j++) {
	    if (pMap->a[j].key == key) {
		pFs = &pMap->a[j].flags;
		break;
	    }
	}
    }

    if (!zHave || nHave == 0) return 1; /* have-none */
    if (!pFs) return 0;

    /* In strict mode, reject if any character is invalid. */
    if (bStrict) {
	for (i = 0; i < nHave; i++) {
	    if (!th8AfIsIdentChar(zHave[i])
		    && !th8AfIsWildcard(zHave[i])) {
		return 0;
	    }
	}
    }

    for (i = 0; i < nHave; i++) {
	char c = zHave[i];

	if (th8AfIsWildcard(c)) {
	    if (bAll) {
		if (!th8AfWildcardHaveAll(pFs, c)) return 0;
	    } else {
		if (th8AfWildcardHaveAny(pFs, c)) return 1;
	    }
	    continue;
	}
	if (!th8AfIsIdentChar(c)) {
	    if (bStrict) return 0;
	    continue;
	}
	if (th8AfFlagSetHas(pFs, c)) {
	    if (!bAll) return 1; /* have-any */
	} else {
	    if (bAll) return 0;	/* not-have-all */
	}
    }
    return bAll; /* have-all if bAll, else not-have-any */
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_AttrFlagsChange --
 *
 *	Apply a change specification to a flag map.
 *	The change string is parsed character-by-character:
 *	  +X  = add flag X
 *	  -X  = remove flag X
 *	  =X  = set (clear all, then add X)
 *	  X   = add flag X (default is add)
 *
 *----------------------------------------------------------------------
 */

int
Th8_AttrFlagsChange(
    Th8_Interp *interp,
    Th8_AfMap *pMap,
    const char *zChange,
    size_t nChange,
    th8_int64_t key)
{
    size_t i;
    int mode = AF_ADD_CHAR;  /* default: add */
    Th8_FlagSet *pFs;

    if (!zChange) return TH8_OK;
    if (nChange == TH8_NOLEN) nChange = Th8_Strlen(interp, zChange);

    pFs = th8AfMapGet(interp, pMap, key, 1);
    if (!pFs) {
	Th8_SetResultStatic(interp,
		"flags change: too many keys", TH8_NOLEN);
	return TH8_ERROR;
    }

    for (i = 0; i < nChange; i++) {
	char c = zChange[i];

	if (c == AF_ADD_CHAR || c == AF_REMOVE_CHAR
		|| c == AF_SET_CHAR) {
	    if (c == AF_SET_CHAR) {
		/* Clear all flags for this key. */
		th8AfFlagSetInit(interp, pFs);
	    }
	    mode = c;
	    continue;
	}
	if (th8AfIsWildcard(c)) {
	    if (mode == AF_REMOVE_CHAR) {
		th8AfExpandWildcard(c, pFs, th8AfFlagSetRemove);
	    } else {
		th8AfExpandWildcard(c, pFs, th8AfFlagSetAdd);
	    }
	    continue;
	}
	if (!th8AfIsIdentChar(c)) {
	    Th8_SetResultStatic(interp,
		    "flags change: invalid character",
		    TH8_NOLEN);
	    return TH8_ERROR;
	}
	if (mode == AF_ADD_CHAR || mode == AF_SET_CHAR) {
	    th8AfFlagSetAdd(pFs, c);
	} else {
	    th8AfFlagSetRemove(pFs, c);
	}
    }
    return TH8_OK;
}

