static const size_t th8_keyTime_size = sizeof(th8_keyTime_data);

/*
 * Th8_GetEmbeddedKeyTime --
 *    Returns a pointer to the embedded keyTime data and its size.
 */
const unsigned char *
Th8_GetEmbeddedKeyTime(size_t *pnData)
{
    if (pnData) *pnData = th8_keyTime_size;
    return th8_keyTime_data;
}

