/*
 *----------------------------------------------------------------------
 *
 * th8Win32GetRealPath --
 *
 *	Resolve a path to absolute using GetFullPathNameA.
 *
 *----------------------------------------------------------------------
 */

static int
th8Win32GetRealPath(
    Th8_Interp *interp,
    void *pCtx,
    const char *zPath,
    size_t nPath,
    char *zBuf,
    size_t nBuf)
{
    char zCopy[4096];
    DWORD n;

    (void)interp; (void)pCtx;

    if (!zPath || !zBuf || nBuf == 0) return TH8_ERROR;
    if (nPath == (size_t)-1) nPath = Th8_Strlen(NULL, zPath);
    if (nPath >= sizeof(zCopy)) return TH8_ERROR;

    memcpy(zCopy, zPath, nPath);
    zCopy[nPath] = '\0';

    n = GetFullPathNameA(zCopy, (DWORD)nBuf, zBuf, NULL);
    if (n == 0 || n >= (DWORD)nBuf) return TH8_ERROR;
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * th8Win32GetRootPath --
 *
 *	Return the volume root for a given path using
 *	GetVolumePathNameA (e.g., "C:\\").
 *
 *----------------------------------------------------------------------
 */

static int
th8Win32GetRootPath(
    Th8_Interp *interp,
    void *pCtx,
    const char *zPath,
    size_t nPath,
    char *zBuf,
    size_t nBuf)
{
    char zCopy[4096];

    (void)interp; (void)pCtx;

    if (!zBuf || nBuf < 2) return TH8_ERROR;
    if (!zPath) { zBuf[0] = '\0'; return TH8_OK; }
    if (nPath == (size_t)-1) nPath = Th8_Strlen(NULL, zPath);
    if (nPath >= sizeof(zCopy)) { zBuf[0] = '\0'; return TH8_OK; }

    memcpy(zCopy, zPath, nPath);
    zCopy[nPath] = '\0';

    /*
     * Normalize the path and check whether it resides under
     * the base directory.  Return "." if it does, or "" if
     * the path is outside the sandbox.
     */
    if (th8Win32IsPathUnderBase(zCopy)) {
	zBuf[0] = '.';
	zBuf[1] = '\0';
    } else {
	zBuf[0] = '\0';
    }
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * th8Win32SameFile --
 *
 *	Test whether two paths refer to the same physical file by
 *	comparing volume serial number and file index from
 *	GetFileInformationByHandle.
 *
 *----------------------------------------------------------------------
 */

static int
th8Win32SameFile(
    Th8_Interp *interp,
    void *pCtx,
    const char *zName1,
    size_t nName1,
    const char *zName2,
    size_t nName2)
{
    char zCopy1[4096];
    char zCopy2[4096];
    HANDLE h1;
    HANDLE h2;
    BY_HANDLE_FILE_INFORMATION info1;
    BY_HANDLE_FILE_INFORMATION info2;
    int result = 0;

    (void)interp; (void)pCtx;

    if (!zName1 || !zName2) return 0;
    if (nName1 == (size_t)-1) nName1 = Th8_Strlen(NULL, zName1);
    if (nName2 == (size_t)-1) nName2 = Th8_Strlen(NULL, zName2);
    if (nName1 >= sizeof(zCopy1)) return 0;
    if (nName2 >= sizeof(zCopy2)) return 0;

    memcpy(zCopy1, zName1, nName1);
    zCopy1[nName1] = '\0';
    memcpy(zCopy2, zName2, nName2);
    zCopy2[nName2] = '\0';

    /*
     * Both paths must be under the base directory.
     */
    if (!th8Win32IsPathUnderBase(zCopy1)) return 0;
    if (!th8Win32IsPathUnderBase(zCopy2)) return 0;

    h1 = CreateFileA(zCopy1, 0,
	    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
	    NULL, OPEN_EXISTING,
	    FILE_FLAG_BACKUP_SEMANTICS, NULL);
    if (h1 == INVALID_HANDLE_VALUE) return 0;

    h2 = CreateFileA(zCopy2, 0,
	    FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
	    NULL, OPEN_EXISTING,
	    FILE_FLAG_BACKUP_SEMANTICS, NULL);
    if (h2 == INVALID_HANDLE_VALUE) {
	CloseHandle(h1);
	return 0;
    }

    if (GetFileInformationByHandle(h1, &info1)
	    && GetFileInformationByHandle(h2, &info2)) {
	result = (info1.dwVolumeSerialNumber
		    == info2.dwVolumeSerialNumber
		&& info1.nFileIndexHigh == info2.nFileIndexHigh
		&& info1.nFileIndexLow == info2.nFileIndexLow);
    } else {
	TH8_TRACE_ERR(NULL, "GetFileInformationByHandle failed");
    }

    CloseHandle(h1);
    CloseHandle(h2);
    return result;
}


