/*
 *----------------------------------------------------------------------
 *
 * Fault-injecting callback wrappers.
 *
 *----------------------------------------------------------------------
 */

static void *
fi_xMalloc(Th8_Interp *i, void *c, size_t n)
{
    Th8_FaultCtx *pF = (Th8_FaultCtx *)c;

    if (th8FaultShouldFailAlloc(pF->pConfig)) return NULL;
    if (REAL(c)->xMalloc)
	return REAL(c)->xMalloc(i, RCTX(c), n);
    return NULL;
}

static void *
fi_xRealloc(Th8_Interp *i, void *c, void *p, size_t n)
{
    Th8_FaultCtx *pF = (Th8_FaultCtx *)c;

    if (th8FaultShouldFailAlloc(pF->pConfig)) return NULL;
    if (REAL(c)->xRealloc)
	return REAL(c)->xRealloc(i, RCTX(c), p, n);
    return NULL;
}

static void
fi_xFree(Th8_Interp *i, void *c, void *p)
{
    /* Never fault  leaking is not a useful test. */
    if (REAL(c)->xFree) REAL(c)->xFree(i, RCTX(c), p);
}

static size_t
fi_xMemorySize(Th8_Interp *i, void *c, void *p)
{
    if (REAL(c)->xMemorySize)
	return REAL(c)->xMemorySize(i, RCTX(c), p);
    return 0;
}

static int
fi_xGetData(Th8_Interp *i, void *c,
    const char *zN, size_t nN, char **pzO, size_t *pnO)
{
    Th8_FaultCtx *pF = (Th8_FaultCtx *)c;

    pF->pConfig->nGetDataCount++;
    if (pF->pConfig->bFailGetData) {
	pF->pConfig->nGetDataFailCount++;
	*pzO = 0; *pnO = 0;
	return TH8_ERROR;
    }
    if (REAL(c)->xGetData)
	return REAL(c)->xGetData(i, RCTX(c), zN, nN, pzO, pnO);
    *pzO = 0; *pnO = 0;
    return TH8_ERROR;
}

static int
fi_xDataExists(Th8_Interp *i, void *c,
    const char *zN, size_t nN, int *pA)
{
    Th8_FaultCtx *pF = (Th8_FaultCtx *)c;

    if (pF->pConfig->bFailDataExists) return 0;
    if (REAL(c)->xDataExists)
	return REAL(c)->xDataExists(i, RCTX(c), zN, nN, pA);
    return 0;
}

static int
fi_xRandomBytes(Th8_Interp *i, void *c, void *pBuf, size_t nByte)
{
    Th8_FaultCtx *pF = (Th8_FaultCtx *)c;

    if (pF->pConfig->bFailRandomBytes) return TH8_ERROR;
    if (REAL(c)->xRandomBytes)
	return REAL(c)->xRandomBytes(i, RCTX(c), pBuf, nByte);
    return TH8_ERROR;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_FaultConfigInit --
 *
 *	Initialize fault config to safe defaults (no faults injected).
 *
 *----------------------------------------------------------------------
 */

void
Th8_FaultConfigInit(Th8_FaultConfig *pCfg)
{
    if (!pCfg) return;
    pCfg->nAllocFailAfter = 0;
    pCfg->nAllocFailInterval = 0;
    pCfg->bFailGetData = 0;
    pCfg->bFailDataExists = 0;
    pCfg->bFailRandomBytes = 0;
    pCfg->nAllocCount = 0;
    pCfg->nAllocFailCount = 0;
    pCfg->nGetDataCount = 0;
    pCfg->nGetDataFailCount = 0;
}


/*
 *----------------------------------------------------------------------
 *
 * th8FaultWireCallbacks --
 *
 *	Wire up ALL callbacks on the fault platform.  For each
 *	callback slot: if the real platform has it, install the
 *	passthrough (or fault-injecting) wrapper.  Otherwise NULL.
 *
 *----------------------------------------------------------------------
 */

static void
th8FaultWireCallbacks(
    Th8_Platform *pF,		/* Fault platform to populate. */
    const Th8_Platform *pR)	/* Real platform (read-only). */
{
    pF->nVersion = pR->nVersion;

    /* Lifecycle */
    pF->xInitialize   = pR->xInitialize   ? pt_xInitialize   : 0;
    pF->xFinalize     = pR->xFinalize     ? pt_xFinalize     : 0;
    pF->xDeleteInterp = pR->xDeleteInterp ? pt_xDeleteInterp : 0;

    /* Memory  fault-injecting wrappers */
    pF->xMalloc     = pR->xMalloc     ? fi_xMalloc     : 0;
    pF->xRealloc    = pR->xRealloc    ? fi_xRealloc    : 0;
    pF->xFree       = pR->xFree       ? fi_xFree       : 0;
    pF->xMemorySize = pR->xMemorySize ? fi_xMemorySize : 0;

    /* Byte operations */
    pF->xMemcpy  = pR->xMemcpy  ? pt_xMemcpy  : 0;
    pF->xMemmove = pR->xMemmove ? pt_xMemmove : 0;
    pF->xMemset  = pR->xMemset  ? pt_xMemset  : 0;
    pF->xMemcmp  = pR->xMemcmp  ? pt_xMemcmp  : 0;

    /* String/utility */
    pF->xStrlen    = pR->xStrlen    ? pt_xStrlen    : 0;
    pF->xStrcmp    = pR->xStrcmp    ? pt_xStrcmp    : 0;
    pF->xStrchr    = pR->xStrchr    ? pt_xStrchr    : 0;
    pF->xAtoi      = pR->xAtoi      ? pt_xAtoi      : 0;
    pF->xQsort     = pR->xQsort     ? pt_xQsort     : 0;
    pF->xVsnprintf = pR->xVsnprintf ? pt_xVsnprintf : 0;

    /* Mutex / sync */
    pF->xMutexInit  = pR->xMutexInit  ? pt_xMutexInit  : 0;
    pF->xMutexFinal = pR->xMutexFinal ? pt_xMutexFinal : 0;
    pF->xMutexEnter = pR->xMutexEnter ? pt_xMutexEnter : 0;
    pF->xMutexLeave = pR->xMutexLeave ? pt_xMutexLeave : 0;
    pF->xIntCmpXchg = pR->xIntCmpXchg ? pt_xIntCmpXchg : 0;
    pF->xMemBarrier = pR->xMemBarrier ? pt_xMemBarrier : 0;

    /* I/O core */
    pF->xInput       = pR->xInput       ? pt_xInput       : 0;
    pF->xOutput      = pR->xOutput      ? pt_xOutput      : 0;
    pF->xOutputError = pR->xOutputError ? pt_xOutputError : 0;

    /* I/O redirection */
    pF->xGetInput        = pR->xGetInput        ? pt_xGetInput        : 0;
    pF->xSetInput        = pR->xSetInput        ? pt_xSetInput        : 0;
    pF->xGetOutput       = pR->xGetOutput       ? pt_xGetOutput       : 0;
    pF->xSetOutput       = pR->xSetOutput       ? pt_xSetOutput       : 0;
    pF->xGetErrorOutput  = pR->xGetErrorOutput  ? pt_xGetErrorOutput  : 0;
    pF->xSetErrorOutput  = pR->xSetErrorOutput  ? pt_xSetErrorOutput  : 0;

    /* Channel / temporary data */
    pF->xChannelControl      = pR->xChannelControl      ? pt_xChannelControl      : 0;
    pF->xGetTemporaryData    = pR->xGetTemporaryData    ? pt_xGetTemporaryData    : 0;
    pF->xDeleteTemporaryData = pR->xDeleteTemporaryData ? pt_xDeleteTemporaryData : 0;
    pF->xSetTemporaryData    = pR->xSetTemporaryData    ? pt_xSetTemporaryData    : 0;
    pF->xCloseTemporaryData  = pR->xCloseTemporaryData  ? pt_xCloseTemporaryData  : 0;

    /* Filesystem */
    pF->xNormalizePath = pR->xNormalizePath ? pt_xNormalizePath : 0;
    pF->xGetCwd        = pR->xGetCwd        ? pt_xGetCwd        : 0;
    pF->xSetCwd        = pR->xSetCwd        ? pt_xSetCwd        : 0;
    pF->xGetExePath    = pR->xGetExePath    ? pt_xGetExePath    : 0;
    pF->xGetRealPath   = pR->xGetRealPath   ? pt_xGetRealPath   : 0;
    pF->xGetRootPath   = pR->xGetRootPath   ? pt_xGetRootPath   : 0;
    pF->xSameFile      = pR->xSameFile      ? pt_xSameFile      : 0;

    /* Data retrieval  fault-injecting wrappers */
    pF->xGetData    = pR->xGetData    ? fi_xGetData    : 0;
    pF->xDataExists = pR->xDataExists ? fi_xDataExists : 0;

    /* Binary loading */
    pF->xLoad   = pR->xLoad   ? pt_xLoad   : 0;
    pF->xUnload = pR->xUnload ? pt_xUnload : 0;

    /* Time */
    pF->xTimeMs = pR->xTimeMs ? pt_xTimeMs : 0;
    pF->xTimeUs = pR->xTimeUs ? pt_xTimeUs : 0;
    pF->xSleep  = pR->xSleep  ? pt_xSleep  : 0;

    /* Process/host */
    pF->xGetPid         = pR->xGetPid         ? pt_xGetPid         : 0;
    pF->xGetUserName    = pR->xGetUserName    ? pt_xGetUserName    : 0;
    pF->xGetHostName    = pR->xGetHostName    ? pt_xGetHostName    : 0;
    pF->xGetEnv         = pR->xGetEnv         ? pt_xGetEnv         : 0;
    pF->xKeyValue       = pR->xKeyValue       ? pt_xKeyValue       : 0;
    pF->xGetStackBounds = pR->xGetStackBounds ? pt_xGetStackBounds : 0;
    pF->xGetParentPid   = pR->xGetParentPid   ? pt_xGetParentPid   : 0;
    pF->xGetThreadId    = pR->xGetThreadId    ? pt_xGetThreadId    : 0;

    /* Error/diagnostics */
    pF->xGetLastError = pR->xGetLastError ? pt_xGetLastError : 0;
    pF->xSetLastError = pR->xSetLastError ? pt_xSetLastError : 0;
    pF->xEmitTrace    = pR->xEmitTrace    ? pt_xEmitTrace    : 0;
    pF->xPanic        = pR->xPanic        ? pt_xPanic        : 0;

    /* Math / entropy  xRandomBytes is fault-injecting */
    pF->xMathFunc    = pR->xMathFunc    ? pt_xMathFunc    : 0;
    pF->xRandomBytes = pR->xRandomBytes ? fi_xRandomBytes : 0;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_FaultInstall --
 *
 *	Dynamically install the fault-injection layer on a running
 *	interpreter.  Saves the current platform and swaps in the
 *	fault-wrapping platform.
 *
 *	pConfig and pCtx must remain valid until Th8_FaultUninstall.
 *	Stack allocation is fine for single-function test sequences.
 *
 *----------------------------------------------------------------------
 */

int
Th8_FaultInstall(
    Th8_Interp *interp,
    Th8_FaultConfig *pConfig,
    Th8_FaultCtx *pCtx)
{
    if (!interp || !pConfig || !pCtx) return TH8_ERROR;

    /* Save the current platform pointer. */
    pCtx->pSavedPlatform = interp->pPlatform;
    pCtx->pConfig = pConfig;

    /* Build the fault platform with proper passthroughs. */
    th8FaultWireCallbacks(&pCtx->faultPlatform,
	    interp->pPlatform);
    pCtx->faultPlatform.pCtx = pCtx;

    /* Swap the interpreter's platform pointer. */
    interp->pPlatform = &pCtx->faultPlatform;

    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_FaultUninstall --
 *
 *	Remove the fault-injection layer from a running interpreter.
 *	Restores the original platform.  After this call, pCtx may
 *	be freed or go out of scope.
 *
 *----------------------------------------------------------------------
 */

int
Th8_FaultUninstall(
    Th8_Interp *interp,
    Th8_FaultCtx *pCtx)
{
    if (!interp || !pCtx) return TH8_ERROR;
    if (!pCtx->pSavedPlatform) return TH8_ERROR;

    /* Restore the original platform. */
    interp->pPlatform = pCtx->pSavedPlatform;
    pCtx->pSavedPlatform = 0;

    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * Th8_FaultCtxSize --
 *
 *	Return sizeof(Th8_FaultCtx) so external callers can allocate
 *	the context without including internal headers.
 *
 *----------------------------------------------------------------------
 */

size_t
Th8_FaultCtxSize(void)
{
    return sizeof(Th8_FaultCtx);
}


#endif /* TH8_ENABLE_FAULT_INJECTION */

/************** End of th8_fault.c **************/

/************** Begin file th8_env.c **************/
/*
 * th8_env.c -- Environment variable key-value platform for TH8.
 *
 * Provides an xKeyValue callback backed by the host process
 * environment variables.  Supports EXISTS, LIST, GET, SET,
 * and UNSET operations.
 *
 * POSIX: getenv, setenv, unsetenv, extern environ for LIST.
 * Win32: GetEnvironmentVariableW, SetEnvironmentVariableW,
 *        GetEnvironmentStringsW for LIST.  UTF-8 <-> UTF-16
 *        conversion via ConvertUTF_v2 with strict validation.
 *
 * Thread safety: a file-scope mutex serializes all operations.
 *
 * Compile-time gate: always compiled (no gate required).
 *
 * Usage:
 *   Th8_Platform plat;
 *   Th8_UseDefaultPlatform(&plat);  // merges env automatically
 *
 * Copyright (c) 2026 by Joe Mistachkin.  All rights reserved.
 *
 * See the file "license.terms" for information on usage and redistribution of
 * this file, and for a DISCLAIMER OF ALL WARRANTIES.
 */

#include "th8.h"

#include <string.h>	/* memcpy, strchr */


/*
 *======================================================================
 * Shared helpers (used by both POSIX and Win32 implementations).
 *======================================================================
 */


/*
 *----------------------------------------------------------------------
 *
 * th8EnvNulTerminate --
 *
 *	Copy a length-counted TH8 string into a NUL-terminated
 *	buffer.  Uses the stack buffer if it fits; otherwise
 *	allocates via Th8_AttemptMalloc.  Returns NULL on OOM.
 *
 *	The caller must call th8EnvFreeNul() when done.
 *
 *----------------------------------------------------------------------
 */

static char *
th8EnvNulTerminate(
    Th8_Interp *interp,
    const char *z,
    size_t n,
    char *zBuf,		/* Stack buffer. */
    size_t nBuf)	/* Size of stack buffer. */
{
    char *zOut;

    if (n + 1 <= nBuf) {
	memcpy(zBuf, z, n);
	zBuf[n] = '\0';
	return zBuf;
    }
    zOut = (char *)Th8_AttemptMalloc(interp, n + 1);
    if (!zOut) return NULL;
    Th8_Memcpy(interp, zOut, z, n);
    zOut[n] = '\0';
    return zOut;
}

static void
th8EnvFreeNul(
    Th8_Interp *interp,
    char *z,
    char *zBuf)		/* The original stack buffer. */
{
    if (z && z != zBuf) {
	Th8_Free(interp, z);
    }
}


/*
 * Glob matching for LIST operations uses the public Th8_GlobMatch
 * API (th8_glob.c), which is the same algorithm as [string match].
 * Supports *, ?, [...], and \ metacharacters.
 */


/*
 *======================================================================
 *======================================================================
 */

#if !defined(_WIN32) && !defined(WIN32)
/*
 *======================================================================
 * POSIX implementation
 *======================================================================
 */

#include <stdlib.h>	/* getenv, setenv, unsetenv */
#include <pthread.h>

extern char **environ;

/*
 * Lazy-initialized mutex.  Uses the same atomic CAS pattern
 * as th8_posix.c to avoid needing an xInitialize callback
 * (which is not merged by Th8_MergePlatform).
 */

static volatile int th8EnvMutexReady = 0;
static pthread_mutex_t th8EnvMutex;

static void
th8EnvLock(void)
{
    if (!th8EnvMutexReady) {
	if (__sync_val_compare_and_swap(&th8EnvMutexReady, 0, -1) == 0) {
	    pthread_mutex_init(&th8EnvMutex, NULL);
	    __sync_synchronize();
	    th8EnvMutexReady = 1;
	} else {
	    while (th8EnvMutexReady != 1) {
		/* spin until initialization completes */
	    }
	    __sync_synchronize();
	}
    }
    pthread_mutex_lock(&th8EnvMutex);
}

static void
th8EnvUnlock(void)
{
    pthread_mutex_unlock(&th8EnvMutex);
}


/*
 *----------------------------------------------------------------------
 *
 * th8EnvKeyValue --
 *
 *	xKeyValue callback backed by POSIX environment variables.
 *
 *----------------------------------------------------------------------
 */

static int
th8EnvKeyValue(
    Th8_Interp *interp,
    void *pCtx,
    int op,
    const char *zName,
    size_t nName,
    const char *zValue,
    size_t nValue)
{
    char zNameBuf[256];
    char zValBuf[256];
    char *zNameNul = NULL;
    char *zValNul = NULL;
    int rc = TH8_ERROR;

    (void)pCtx;

    switch (op) {

    case TH8_KV_EXISTS: {
	zNameNul = th8EnvNulTerminate(interp, zName, nName,
		zNameBuf, sizeof(zNameBuf));
	if (!zNameNul) {
	    Th8_SetResultStatic(interp,
		    "out of memory", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	rc = getenv(zNameNul) ? TH8_OK : TH8_ERROR;
	th8EnvUnlock();
	break;
    }

    case TH8_KV_GET: {
	const char *zVal;

	zNameNul = th8EnvNulTerminate(interp, zName, nName,
		zNameBuf, sizeof(zNameBuf));
	if (!zNameNul) {
	    Th8_SetResultStatic(interp,
		    "out of memory", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	zVal = getenv(zNameNul);
	if (zVal) {
	    Th8_SetResult(interp, zVal, TH8_NOLEN);
	    rc = TH8_OK;
	} else {
	    Th8_SetResultStatic(interp,
		    "key not found", TH8_NOLEN);
	}
	th8EnvUnlock();
	break;
    }

    case TH8_KV_SET: {
	zNameNul = th8EnvNulTerminate(interp, zName, nName,
		zNameBuf, sizeof(zNameBuf));
	if (!zNameNul) {
	    Th8_SetResultStatic(interp,
		    "out of memory", TH8_NOLEN);
	    break;
	}
	zValNul = th8EnvNulTerminate(interp, zValue, nValue,
		zValBuf, sizeof(zValBuf));
	if (!zValNul) {
	    Th8_SetResultStatic(interp,
		    "out of memory", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	rc = (setenv(zNameNul, zValNul, 1) == 0)
		? TH8_OK : TH8_ERROR;
	th8EnvUnlock();
	if (rc != TH8_OK) {
	    Th8_SetResultStatic(interp,
		    "setenv failed", TH8_NOLEN);
	}
	break;
    }

    case TH8_KV_UNSET: {
	zNameNul = th8EnvNulTerminate(interp, zName, nName,
		zNameBuf, sizeof(zNameBuf));
	if (!zNameNul) {
	    Th8_SetResultStatic(interp,
		    "out of memory", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	unsetenv(zNameNul);
	th8EnvUnlock();
	rc = TH8_OK;
	break;
    }

    case TH8_KV_LIST: {
	char *zList = NULL;
	size_t nList = 0;
	int i;

	th8EnvLock();
	for (i = 0; environ[i]; i++) {
	    const char *zEntry = environ[i];
	    const char *zEq = strchr(zEntry, '=');
	    size_t nKey;

	    if (!zEq) continue;
	    nKey = (size_t)(zEq - zEntry);

	    if (zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName, zEntry, nKey)) {
		    continue;
		}
	    }
	    Th8_ListAppend(interp, &zList, &nList, zEntry, nKey);
	}
	th8EnvUnlock();

	if (zList) {
	    Th8_SetResult(interp, zList, nList);
	    Th8_Free(interp, zList);
	} else {
	    Th8_SetResultStatic(interp, "", 0);
	}
	rc = TH8_OK;
	break;
    }

    case TH8_KV_EXISTS2: {
	int i;
	int found = 0;

	th8EnvLock();
	for (i = 0; environ[i] && !found; i++) {
	    const char *zEntry = environ[i];
	    const char *zEq = strchr(zEntry, '=');
	    size_t nKey;

	    if (!zEq) continue;
	    nKey = (size_t)(zEq - zEntry);

	    if (zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName,
			zEntry, nKey)) {
		    continue;
		}
	    }
	    if (zValue && nValue > 0) {
		if (!Th8_GlobMatch(interp, zValue, nValue,
			zEq + 1, strlen(zEq + 1))) {
		    continue;
		}
	    }
	    found = 1;
	}
	th8EnvUnlock();
	rc = found ? TH8_OK : TH8_ERROR;
	break;
    }

    case TH8_KV_LIST2: {
	char *zList = NULL;
	size_t nList = 0;
	int i;

	th8EnvLock();
	for (i = 0; environ[i]; i++) {
	    const char *zEntry = environ[i];
	    const char *zEq = strchr(zEntry, '=');
	    size_t nKey;

	    if (!zEq) continue;
	    nKey = (size_t)(zEq - zEntry);

	    if (zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName,
			zEntry, nKey)) {
		    continue;
		}
	    }
	    if (zValue && nValue > 0) {
		if (!Th8_GlobMatch(interp, zValue, nValue,
			zEq + 1, strlen(zEq + 1))) {
		    continue;
		}
	    }
	    Th8_ListAppend(interp, &zList, &nList, zEntry, nKey);
	}
	th8EnvUnlock();

	if (zList) {
	    Th8_SetResult(interp, zList, nList);
	    Th8_Free(interp, zList);
	} else {
	    Th8_SetResultStatic(interp, "", 0);
	}
	rc = TH8_OK;
	break;
    }

    case TH8_KV_GET2: {
	char *zDict = NULL;
	size_t nDict = 0;
	int i;

	th8EnvLock();
	for (i = 0; environ[i]; i++) {
	    const char *zEntry = environ[i];
	    const char *zEq = strchr(zEntry, '=');
	    size_t nKey;
	    const char *zVal;
	    size_t nVal;

	    if (!zEq) continue;
	    nKey = (size_t)(zEq - zEntry);
	    zVal = zEq + 1;
	    nVal = strlen(zVal);

	    if (zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName,
			zEntry, nKey)) {
		    continue;
		}
	    }
	    if (zValue && nValue > 0) {
		if (!Th8_GlobMatch(interp, zValue, nValue,
			zVal, nVal)) {
		    continue;
		}
	    }
	    Th8_ListAppend(interp, &zDict, &nDict, zEntry, nKey);
	    Th8_ListAppend(interp, &zDict, &nDict, zVal, nVal);
	}
	th8EnvUnlock();

	if (zDict) {
	    Th8_SetResult(interp, zDict, nDict);
	    Th8_Free(interp, zDict);
	} else {
	    Th8_SetResultStatic(interp, "", 0);
	}
	rc = TH8_OK;
	break;
    }

    case TH8_KV_SET2: {
	/*
	 * Collect matching key names first, then mutate.
	 * setenv() can reallocate environ, invalidating
	 * iteration pointers.
	 */

	char *zKeys = NULL;
	size_t nKeys = 0;
	int i;

	zValNul = th8EnvNulTerminate(interp, zValue, nValue,
		zValBuf, sizeof(zValBuf));
	if (!zValNul) {
	    Th8_SetResultStatic(interp,
		    "out of memory", TH8_NOLEN);
	    break;
	}

	th8EnvLock();
	for (i = 0; environ[i]; i++) {
	    const char *zEntry = environ[i];
	    const char *zEq = strchr(zEntry, '=');
	    size_t nKey;

	    if (!zEq) continue;
	    nKey = (size_t)(zEq - zEntry);

	    if (zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName,
			zEntry, nKey)) {
		    continue;
		}
	    }
	    Th8_ListAppend(interp, &zKeys, &nKeys, zEntry, nKey);
	}

	/*
	 * Now iterate the collected keys and set each.
	 */

	if (zKeys) {
	    char **azElem = NULL;
	    size_t *anElem = NULL;
	    int nCount = 0;
	    int j;

	    if (Th8_SplitList(interp, zKeys, nKeys,
		    &azElem, &anElem, &nCount) == TH8_OK) {
		for (j = 0; j < nCount; j++) {
		    char kBuf[256];
		    char *kNul = th8EnvNulTerminate(interp,
			    azElem[j], anElem[j],
			    kBuf, sizeof(kBuf));
		    if (kNul) {
			setenv(kNul, zValNul, 1);
			th8EnvFreeNul(interp, kNul, kBuf);
		    }
		}
		Th8_Free(interp, azElem);
		Th8_Free(interp, anElem);
	    }
	    Th8_Free(interp, zKeys);
	}
	th8EnvUnlock();
	rc = TH8_OK;
	break;
    }

    case TH8_KV_UNSET2: {
	/*
	 * Collect matching key-value pairs first, then delete.
	 * unsetenv() can modify environ, invalidating iteration.
	 */

	char *zDict = NULL;
	size_t nDict = 0;
	char *zKeys = NULL;
	size_t nKeys = 0;
	int i;

	th8EnvLock();
	for (i = 0; environ[i]; i++) {
	    const char *zEntry = environ[i];
	    const char *zEq = strchr(zEntry, '=');
	    size_t nKey;
	    const char *zVal;
	    size_t nVal;

	    if (!zEq) continue;
	    nKey = (size_t)(zEq - zEntry);
	    zVal = zEq + 1;
	    nVal = strlen(zVal);

	    if (zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName,
			zEntry, nKey)) {
		    continue;
		}
	    }
	    if (zValue && nValue > 0) {
		if (!Th8_GlobMatch(interp, zValue, nValue,
			zVal, nVal)) {
		    continue;
		}
	    }
	    Th8_ListAppend(interp, &zDict, &nDict, zEntry, nKey);
	    Th8_ListAppend(interp, &zDict, &nDict, zVal, nVal);
	    Th8_ListAppend(interp, &zKeys, &nKeys, zEntry, nKey);
	}

	/*
	 * Delete collected keys.
	 */

	if (zKeys) {
	    char **azElem = NULL;
	    size_t *anElem = NULL;
	    int nCount = 0;
	    int j;

	    if (Th8_SplitList(interp, zKeys, nKeys,
		    &azElem, &anElem, &nCount) == TH8_OK) {
		for (j = 0; j < nCount; j++) {
		    char kBuf[256];
		    char *kNul = th8EnvNulTerminate(interp,
			    azElem[j], anElem[j],
			    kBuf, sizeof(kBuf));
		    if (kNul) {
			unsetenv(kNul);
			th8EnvFreeNul(interp, kNul, kBuf);
		    }
		}
		Th8_Free(interp, azElem);
		Th8_Free(interp, anElem);
	    }
	    Th8_Free(interp, zKeys);
	}
	th8EnvUnlock();

	if (zDict) {
	    Th8_SetResult(interp, zDict, nDict);
	    Th8_Free(interp, zDict);
	} else {
	    Th8_SetResultStatic(interp, "", 0);
	}
	rc = TH8_OK;
	break;
    }

    default:
	Th8_SetResultStatic(interp,
		"unknown kv operation", TH8_NOLEN);
	break;
    }

    th8EnvFreeNul(interp, zNameNul, zNameBuf);
    th8EnvFreeNul(interp, zValNul, zValBuf);
    return rc;
}


#else /* _WIN32 */
/*
 *======================================================================
 * Win32 implementation
 *
 * Uses ConvertUTF_v2 with strict validation for all UTF-8 <-> UTF-16
 * conversions.  Environment variable APIs are all wide-character
 * (GetEnvironmentVariableW, SetEnvironmentVariableW,
 * GetEnvironmentStringsW / FreeEnvironmentStringsW).
 *======================================================================
 */

#include <windows.h>
/* amalgamation: ConvertUTF_v2.h already included */


/*
 * Lazy-initialized CRITICAL_SECTION for thread safety.
 */

static CRITICAL_SECTION th8EnvCritSec;
static volatile LONG th8EnvCritSecReady = 0;

static void
th8EnvLock(void)
{
    if (!th8EnvCritSecReady) {
	if (InterlockedCompareExchange(&th8EnvCritSecReady, -1, 0) == 0) {
	    InitializeCriticalSection(&th8EnvCritSec);
	    InterlockedExchange(&th8EnvCritSecReady, 1);
	} else {
	    while (th8EnvCritSecReady != 1) {
		/* spin until initialization completes */
	    }
	}
    }
    EnterCriticalSection(&th8EnvCritSec);
}

static void
th8EnvUnlock(void)
{
    LeaveCriticalSection(&th8EnvCritSec);
}


/*
 *----------------------------------------------------------------------
 *
 * th8EnvUtf8ToUtf16 --
 *
 *	Convert a length-counted UTF-8 string to a NUL-terminated
 *	UTF-16 string using ConvertUTF_v2 with strict validation.
 *
 *	Uses the stack buffer if it fits; otherwise allocates via
 *	Th8_AttemptMalloc.  Returns NULL on conversion error or OOM.
 *
 *	The caller must call th8EnvFreeWide() when done.
 *
 *----------------------------------------------------------------------
 */

static WCHAR *
th8EnvUtf8ToUtf16(
    Th8_Interp *interp,
    const char *zUtf8,
    size_t nUtf8,
    WCHAR *wBuf,	/* Stack buffer. */
    size_t nBuf)	/* Size in WCHAR units. */
{
    const UTF8 *pSrc;
    UTF16 *pDst;
    ConversionResult cr;
    size_t nWide = nUtf8 + 1;
    WCHAR *wOut;

    if (nWide <= nBuf) {
	wOut = wBuf;
    } else {
	if (nWide > (size_t)-1 / sizeof(WCHAR)) return NULL;
	wOut = (WCHAR *)Th8_AttemptMalloc(interp,
		nWide * sizeof(WCHAR));
	if (!wOut) return NULL;
    }

    pSrc = (const UTF8 *)zUtf8;
    pDst = (UTF16 *)wOut;
    cr = ConvertUTF8toUTF16(
	    &pSrc, (const UTF8 *)(zUtf8 + nUtf8),
	    &pDst, (UTF16 *)(wOut + nWide),
	    strictConversion);

    if (cr != conversionOK) {
	if (wOut != wBuf) Th8_Free(interp, wOut);
	return NULL;
    }
    *pDst = 0;	/* NUL-terminate. */
    return wOut;
}

static void
th8EnvFreeWide(
    Th8_Interp *interp,
    WCHAR *w,
    WCHAR *wBuf)	/* The original stack buffer. */
{
    if (w && w != wBuf) {
	Th8_Free(interp, w);
    }
}


/*
 *----------------------------------------------------------------------
 *
 * th8EnvUtf16ToUtf8 --
 *
 *	Convert a NUL-terminated UTF-16 string to a length-counted
 *	UTF-8 string using ConvertUTF_v2 with strict validation.
 *
 *	Allocates via Th8_AttemptMalloc.  On success, sets *pzOut
 *	and *pnOut.  Returns TH8_OK or TH8_ERROR.
 *
 *	The caller must free *pzOut via Th8_Free.
 *
 *----------------------------------------------------------------------
 */

static int
th8EnvUtf16ToUtf8(
    Th8_Interp *interp,
    const WCHAR *wStr,
    size_t nWchars,	/* Number of WCHAR units (not bytes). */
    char **pzOut,
    size_t *pnOut)
{
    const UTF16 *pSrc;
    UTF8 *pDst;
    ConversionResult cr;
    size_t nAlloc;
    char *zOut;

    /*
     * Worst case: each UTF-16 code unit -> 3 UTF-8 bytes.
     * Surrogate pairs (2 units) -> 4 UTF-8 bytes, so 3x is safe.
     */

    nAlloc = nWchars * 3 + 1;
    if (nAlloc < nWchars) {
	/* overflow */
	*pzOut = NULL;
	*pnOut = 0;
	return TH8_ERROR;
    }

    zOut = (char *)Th8_AttemptMalloc(interp, nAlloc);
    if (!zOut) {
	*pzOut = NULL;
	*pnOut = 0;
	return TH8_ERROR;
    }

    pSrc = (const UTF16 *)wStr;
    pDst = (UTF8 *)zOut;
    cr = ConvertUTF16toUTF8(
	    &pSrc, (const UTF16 *)(wStr + nWchars),
	    &pDst, (UTF8 *)(zOut + nAlloc),
	    strictConversion);

    if (cr != conversionOK) {
	Th8_Free(interp, zOut);
	*pzOut = NULL;
	*pnOut = 0;
	return TH8_ERROR;
    }

    *pnOut = (size_t)((char *)pDst - zOut);
    *pzOut = zOut;
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * th8EnvKeyValue --
 *
 *	xKeyValue callback backed by Win32 environment variables.
 *	All string conversions use ConvertUTF_v2 with strict mode.
 *
 *----------------------------------------------------------------------
 */

static int
th8EnvKeyValue(
    Th8_Interp *interp,
    void *pCtx,
    int op,
    const char *zName,
    size_t nName,
    const char *zValue,
    size_t nValue)
{
    WCHAR wNameBuf[256];
    WCHAR *wName = NULL;
    int rc = TH8_ERROR;

    (void)pCtx;

    switch (op) {

    case TH8_KV_EXISTS: {
	DWORD n;

	wName = th8EnvUtf8ToUtf16(interp, zName, nName,
		wNameBuf, sizeof(wNameBuf) / sizeof(WCHAR));
	if (!wName) {
	    Th8_SetResultStatic(interp,
		    "invalid UTF-8 in key name", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	n = GetEnvironmentVariableW(wName, NULL, 0);
	th8EnvUnlock();
	rc = (n > 0) ? TH8_OK : TH8_ERROR;
	break;
    }

    case TH8_KV_GET: {
	WCHAR wValBuf[4096];
	DWORD n;

	wName = th8EnvUtf8ToUtf16(interp, zName, nName,
		wNameBuf, sizeof(wNameBuf) / sizeof(WCHAR));
	if (!wName) {
	    Th8_SetResultStatic(interp,
		    "invalid UTF-8 in key name", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	n = GetEnvironmentVariableW(wName, wValBuf,
		sizeof(wValBuf) / sizeof(WCHAR));
	th8EnvUnlock();

	if (n == 0) {
	    Th8_SetResultStatic(interp,
		    "key not found", TH8_NOLEN);
	    break;
	}
	if (n >= sizeof(wValBuf) / sizeof(WCHAR)) {
	    Th8_SetResultStatic(interp,
		    "environment value too long", TH8_NOLEN);
	    break;
	}

	{
	    char *zUtf8 = NULL;
	    size_t nUtf8 = 0;

	    if (th8EnvUtf16ToUtf8(interp, wValBuf, (size_t)n,
		    &zUtf8, &nUtf8) != TH8_OK) {
		Th8_SetResultStatic(interp,
			"UTF-16 to UTF-8 conversion failed",
			TH8_NOLEN);
		break;
	    }
	    Th8_SetResult(interp, zUtf8, nUtf8);
	    Th8_Free(interp, zUtf8);
	    rc = TH8_OK;
	}
	break;
    }

    case TH8_KV_SET: {
	WCHAR wValSetBuf[256];
	WCHAR *wVal = NULL;

	wName = th8EnvUtf8ToUtf16(interp, zName, nName,
		wNameBuf, sizeof(wNameBuf) / sizeof(WCHAR));
	if (!wName) {
	    Th8_SetResultStatic(interp,
		    "invalid UTF-8 in key name", TH8_NOLEN);
	    break;
	}
	wVal = th8EnvUtf8ToUtf16(interp, zValue, nValue,
		wValSetBuf, sizeof(wValSetBuf) / sizeof(WCHAR));
	if (!wVal) {
	    Th8_SetResultStatic(interp,
		    "invalid UTF-8 in value", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	rc = SetEnvironmentVariableW(wName, wVal)
		? TH8_OK : TH8_ERROR;
	th8EnvUnlock();
	th8EnvFreeWide(interp, wVal, wValSetBuf);
	wVal = NULL;
	if (rc != TH8_OK) {
	    Th8_SetResultStatic(interp,
		    "SetEnvironmentVariableW failed", TH8_NOLEN);
	}
	break;
    }

    case TH8_KV_UNSET: {
	wName = th8EnvUtf8ToUtf16(interp, zName, nName,
		wNameBuf, sizeof(wNameBuf) / sizeof(WCHAR));
	if (!wName) {
	    Th8_SetResultStatic(interp,
		    "invalid UTF-8 in key name", TH8_NOLEN);
	    break;
	}
	th8EnvLock();
	SetEnvironmentVariableW(wName, NULL);
	th8EnvUnlock();
	rc = TH8_OK;
	break;
    }

    case TH8_KV_LIST: {
	WCHAR *wEnv;
	const WCHAR *p;
	char *zList = NULL;
	size_t nList = 0;

	th8EnvLock();
	wEnv = GetEnvironmentStringsW();
	th8EnvUnlock();

	if (!wEnv) {
	    Th8_SetResultStatic(interp, "", 0);
	    rc = TH8_OK;
	    break;
	}

	/*
	 * GetEnvironmentStringsW returns a double-NUL-terminated
	 * block of NUL-terminated L"NAME=VALUE" strings.
	 */

	for (p = wEnv; *p; ) {
	    const WCHAR *wEq;
	    size_t nEntry;
	    size_t nKey;

	    nEntry = wcslen(p);
	    wEq = wcschr(p, L'=');
	    if (!wEq || wEq == p) {
		p += nEntry + 1;
		continue;
	    }
	    nKey = (size_t)(wEq - p);

	    {
		/*
		 * Convert the key portion to UTF-8 for glob matching
		 * and list building.
		 */

		char *zKey = NULL;
		size_t nKeyUtf8 = 0;

		if (th8EnvUtf16ToUtf8(interp, p, nKey,
			&zKey, &nKeyUtf8) != TH8_OK) {
		    p += nEntry + 1;
		    continue;	/* skip unconvertible entries */
		}

		if (!zName || nName == 0
			|| Th8_GlobMatch(interp, zName, nName,
			    zKey, nKeyUtf8)) {
		    Th8_ListAppend(interp, &zList, &nList,
			    zKey, nKeyUtf8);
		}
		Th8_Free(interp, zKey);
	    }
	    p += nEntry + 1;
	}

	FreeEnvironmentStringsW(wEnv);

	if (zList) {
	    Th8_SetResult(interp, zList, nList);
	    Th8_Free(interp, zList);
	} else {
	    Th8_SetResultStatic(interp, "", 0);
	}
	rc = TH8_OK;
	break;
    }

    case TH8_KV_EXISTS2:
    case TH8_KV_LIST2:
    case TH8_KV_GET2:
    case TH8_KV_SET2:
    case TH8_KV_UNSET2: {
	WCHAR *wEnv;
	const WCHAR *p2;
	char *zOut = NULL;
	size_t nOut = 0;
	char *zCollect = NULL;
	size_t nCollect = 0;
	int found = 0;

	th8EnvLock();
	wEnv = GetEnvironmentStringsW();

	if (!wEnv) {
	    th8EnvUnlock();
	    if (op == TH8_KV_EXISTS2) {
		rc = TH8_ERROR;
	    } else {
		Th8_SetResultStatic(interp, "", 0);
		rc = TH8_OK;
	    }
	    break;
	}

	for (p2 = wEnv; *p2; ) {
	    const WCHAR *wEq;
	    size_t nEntry2;
	    size_t nWKey;
	    char *zKey2 = NULL;
	    size_t nKey2 = 0;
	    char *zVal2 = NULL;
	    size_t nVal2 = 0;
	    int match;

	    nEntry2 = wcslen(p2);
	    wEq = wcschr(p2, L'=');
	    if (!wEq || wEq == p2) {
		p2 += nEntry2 + 1;
		continue;
	    }
	    nWKey = (size_t)(wEq - p2);

	    if (th8EnvUtf16ToUtf8(interp, p2, nWKey,
		    &zKey2, &nKey2) != TH8_OK) {
		p2 += nEntry2 + 1;
		continue;
	    }
	    if (th8EnvUtf16ToUtf8(interp, wEq + 1,
		    nEntry2 - nWKey - 1,
		    &zVal2, &nVal2) != TH8_OK) {
		Th8_Free(interp, zKey2);
		p2 += nEntry2 + 1;
		continue;
	    }

	    match = 1;
	    if (match && zName && nName > 0) {
		if (!Th8_GlobMatch(interp, zName, nName,
			zKey2, nKey2)) {
		    match = 0;
		}
	    }
	    if (match && op != TH8_KV_SET2
		    && zValue && nValue > 0) {
		if (!Th8_GlobMatch(interp, zValue, nValue,
			zVal2, nVal2)) {
		    match = 0;
		}
	    }

	    if (match) {
		found = 1;

		if (op == TH8_KV_EXISTS2) {
		    Th8_Free(interp, zKey2);
		    Th8_Free(interp, zVal2);
		    break;
		}
		if (op == TH8_KV_LIST2) {
		    Th8_ListAppend(interp, &zOut, &nOut,
			    zKey2, nKey2);
		}
		if (op == TH8_KV_GET2) {
		    Th8_ListAppend(interp, &zOut, &nOut,
			    zKey2, nKey2);
		    Th8_ListAppend(interp, &zOut, &nOut,
			    zVal2, nVal2);
		}
		if (op == TH8_KV_SET2 || op == TH8_KV_UNSET2) {
		    Th8_ListAppend(interp, &zCollect, &nCollect,
			    zKey2, nKey2);
		}
		if (op == TH8_KV_UNSET2) {
		    Th8_ListAppend(interp, &zOut, &nOut,
			    zKey2, nKey2);
		    Th8_ListAppend(interp, &zOut, &nOut,
			    zVal2, nVal2);
		}
	    }

	    Th8_Free(interp, zKey2);
	    Th8_Free(interp, zVal2);
	    p2 += nEntry2 + 1;
	}

	FreeEnvironmentStringsW(wEnv);

	/*
	 * For SET2/UNSET2, mutate after iteration.
	 */

	if (zCollect) {
	    WCHAR wValSetBuf2[256];
	    WCHAR *wVal2 = NULL;
	    char **azElem = NULL;
	    size_t *anElem = NULL;
	    int nCount = 0;
	    int j;

	    if (op == TH8_KV_SET2) {
		wVal2 = th8EnvUtf8ToUtf16(interp, zValue, nValue,
			wValSetBuf2,
			sizeof(wValSetBuf2) / sizeof(WCHAR));
	    }

	    if (Th8_SplitList(interp, zCollect, nCollect,
		    &azElem, &anElem, &nCount) == TH8_OK) {
		for (j = 0; j < nCount; j++) {
		    WCHAR wKBuf[256];
		    WCHAR *wK = th8EnvUtf8ToUtf16(interp,
			    azElem[j], anElem[j],
			    wKBuf, sizeof(wKBuf) / sizeof(WCHAR));
		    if (wK) {
			if (op == TH8_KV_SET2 && wVal2) {
			    SetEnvironmentVariableW(wK, wVal2);
			} else if (op == TH8_KV_UNSET2) {
			    SetEnvironmentVariableW(wK, NULL);
			}
			th8EnvFreeWide(interp, wK, wKBuf);
		    }
		}
		Th8_Free(interp, azElem);
		Th8_Free(interp, anElem);
	    }

	    if (op == TH8_KV_SET2) {
		th8EnvFreeWide(interp, wVal2, wValSetBuf2);
	    }
	    Th8_Free(interp, zCollect);
	}

	th8EnvUnlock();

	if (op == TH8_KV_EXISTS2) {
	    rc = found ? TH8_OK : TH8_ERROR;
	} else {
	    if (zOut) {
		Th8_SetResult(interp, zOut, nOut);
		Th8_Free(interp, zOut);
	    } else {
		Th8_SetResultStatic(interp, "", 0);
	    }
	    rc = TH8_OK;
	}
	break;
    }

    default:
	Th8_SetResultStatic(interp,
		"unknown kv operation", TH8_NOLEN);
	break;
    }

    th8EnvFreeWide(interp, wName, wNameBuf);
    return rc;
}


#endif /* _WIN32 */


